INSERT INTO google_book values ("UYs7DwAAQBAJ", "朝鮮漢字音　入門と発展", '{"kind":"books#volume","id":"UYs7DwAAQBAJ","etag":"GS1NqyP65GI","selfLink":"https://www.googleapis.com/books/v1/volumes/UYs7DwAAQBAJ","volumeInfo":{"title":"朝鮮漢字音　入門と発展","authors":["菅野裕臣"],"publisher":"三修社","publishedDate":"2017-11","description":"漢字はその形と意味だけでなくその音（おん）も朝鮮、日本、ヴェトナムに伝わり、中国の主要な言語（漢語）としての漢文がそれらの国で用いられただけでなく、漢字からなる多くの単語（漢字語）がそれらの国に流入し、さらには漢字を組み合わせて新しい単語が作られたりして、それらの国の言語に対する漢字の影響は計り知れないものがある。 本書は朝鮮語における漢語の存在を日本語と比較しながら説明した中級レベルの学習者に最適な一冊。","industryIdentifiers":[{"type":"ISBN_13","identifier":"9784384058796"},{"type":"ISBN_10","identifier":"4384058799"}],"readingModes":{"text":false,"image":true},"pageCount":281,"printType":"BOOK","categories":["Literary Collections"],"maturityRating":"NOT_MATURE","allowAnonLogging":false,"contentVersion":"1.1.0.0.preview.1","panelizationSummary":{"containsEpubBubbles":false,"containsImageBubbles":false},"imageLinks":{"smallThumbnail":"http://books.google.com/books/content?id=UYs7DwAAQBAJ&printsec=frontcover&img=1&zoom=5&edge=curl&source=gbs_api","thumbnail":"http://books.google.com/books/content?id=UYs7DwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api"},"language":"ja","previewLink":"http://books.google.co.jp/books?id=UYs7DwAAQBAJ&pg=PA119&dq=%E3%81%86&hl=&cd=2&source=gbs_api","infoLink":"http://books.google.co.jp/books?id=UYs7DwAAQBAJ&dq=%E3%81%86&hl=&source=gbs_api","canonicalVolumeLink":"https://books.google.com/books/about/%E6%9C%9D%E9%AE%AE%E6%BC%A2%E5%AD%97%E9%9F%B3_%E5%85%A5%E9%96%80%E3%81%A8%E7%99%BA%E5%B1%95.html?hl=&id=UYs7DwAAQBAJ"},"saleInfo":{"country":"JP","saleability":"NOT_FOR_SALE","isEbook":false},"accessInfo":{"country":"JP","viewability":"PARTIAL","embeddable":true,"publicDomain":false,"textToSpeechPermission":"ALLOWED","epub":{"isAvailable":false},"pdf":{"isAvailable":true,"acsTokenLink":"http://books.google.co.jp/books/download/%E6%9C%9D%E9%AE%AE%E6%BC%A2%E5%AD%97%E9%9F%B3_%E5%85%A5%E9%96%80%E3%81%A8%E7%99%BA%E5%B1%95-s