INSERT INTO google_book values ("gEhYEQAAQBAJ", "転移したら奴隷の父になったけど、家族として愛でることにした～実は勇者と魔王と聖女だった子供たちの力がとんでもスキルで使えたので最強です～【分冊版】3巻", '{"kind":"books#volume","id":"gEhYEQAAQBAJ","etag":"36QVNG76U9o","selfLink":"https://www.googleapis.com/books/v1/volumes/gEhYEQAAQBAJ","volumeInfo":{"title":"転移したら奴隷の父になったけど、家族として愛でることにした～実は勇者と魔王と聖女だった子供たちの力がとんでもスキルで使えたので最強です～【分冊版】3巻","authors":["えむだ","御峰。"],"publisher":"スターツ出版","description":"【転移したら、魔王・勇者・聖女の父に!? 最強な子供たちとの親子無双大冒険、開幕！】 孤独な人生の末、異世界に転移したアラタ。女神から授かったのは、正体不明の謎スキル【命の鎖】と、奴隷として扱われていた３人の子供たち。戸惑いながらも、アラタは彼らと「家族」として生きることを決意する。 しかし子供たちは、「魔王」「勇者」「聖女」――世界を揺るがすほどの規格外の才能を秘めていた！ さらに【命の鎖】は、絆を結んだ相手の力を使うことができるとんでもスキルで!? 不器用ながらも父として子供たちを守り抜こうと奮闘するアラタと、少しずつ深まる家族の絆。その絆が固く結ばれた時、アラタは真の力に目覚める――！ 最強の才能を持つ子供たちとの親子無双の冒険譚、ここに開幕！ （この作品は電子コミック誌comicグラスト89号に収録されています。重複購入にご注意ください）","industryIdentifiers":[{"type":"OTHER","identifier":"PKEY:BT000185813600300301900209"}],"readingModes":{"text":true,"image":true},"pageCount":34,"printType":"BOOK","categories":["Comics & Graphic Novels"],"maturityRating":"NOT_MATURE","allowAnonLogging":true,"contentVersion":"1.1.1.0.preview.3","panelizationSummary":{"containsEpubBubbles":true,"containsImageBubbles":true,"epubBubbleVersion":"c00972523f9e5184_A","imageBubbleVersion":"c00972523f9e5184_A"},"imageLinks":{"smallThumbnail":"http://books.google.com/books/content?id=gEhYEQAAQBAJ&printsec=frontcover&img=1&zoom=5&edge=curl&source=gbs_api","thumbnail":"http://books.google.com/books/content?id=gEhYEQAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api"},"language":"ja","previewLink":"http://books.google.co.jp/books?id=gEhYEQAAQBAJ&pg=RA1-PA5&dq=%E3%81%9F&hl=&cd=1&source=gbs_api","infoLink":"https://play.google.com/store/books/details?id=gEhYEQAAQBAJ&source=gbs_api","canonicalVolumeLink":"https://play.google.com/store/books/details?id=gEhYEQAAQBAJ","seriesInfo":{"kind":"books#volume_series_info","bookDisplayNumber":"3","volumeSeries":[{"seriesId":"QaZuHAAAABAuuM","seriesBookType":"COLLECTED_EDITION","orderNumber":