INSERT INTO google_book values ("7ObmBQAAQBAJ", "Orestie", '{"kind":"books#volume","id":"7ObmBQAAQBAJ","etag":"aTd9pxlDMfE","selfLink":"https://www.googleapis.com/books/v1/volumes/7ObmBQAAQBAJ","volumeInfo":{"title":"Orestie","authors":["Aischylos"],"publisher":"Walter de Gruyter","publishedDate":"2014-03-28","description":"Jetzt beim Akademie Verlag: Sammlung Tusculum - die berühmte zweisprachige Bibliothek der Antike! Die 1923 gegründete Sammlung Tusculum umfasst ca. 200 klassische Werke der griechischen und lateinischen Literatur des Altertums und bildet damit das Fundament der abendländischen Geistesgeschichte ab. Die Werke Ciceros, Ovids und Horaz’ gehören ebenso zum Programm wie die philosophischen Schriften Platons, die Dramen des Sophokles oder die enzyklopädische Naturgeschichte des Plinius. Die Reihe bietet die weltliterarisch bedeutenden Originaltexte zusammen mit exzellenten deutschen Übersetzungen und kurzen Sachkommentaren. Von renommierten Altphilologen betreut, präsentiert Tusculum zuverlässige Standardausgaben mit klassischer Einbandgestaltung für Wissenschaftler und Bibliotheken, Studenten und Lehrer sowie das allgemeine Publikum mit Interesse an antiker Dichtung und Philosophie. Der Name der Reihe geht auf die ehemalige Stadt Tusculum in Latium zurück, in der Cicero eine Villa besaß, die ihm als Refugium diente und in der er die Tuskulanen verfasste. Neben der hochwertig ausgestatteten Hauptreihe erscheinen in der Serie Tusculum Studienausgaben einschlägige Texte für Universität und Schule im Taschenbuch. Im Akademie Verlag startet die Reihe 2011 mit sieben wichtigen Neuerscheinungen.","industryIdentifiers":[{"type":"ISBN_13","identifier":"9783110357325"},{"type":"ISBN_10","identifier":"3110357321"}],"readingModes":{"text":false,"image":true},"pageCount":340,"printType":"BOOK","categories":["Literary Criticism"],"maturityRating":"NOT_MATURE","allowAnonLogging":false,"contentVersion":"1.2.1.0.preview.1","panelizationSummary":{"containsEpubBubbles":