INSERT INTO google_book values ("3jqRDwAAQBAJ", "jap形容詞研究入門. 下", '{"kind":"books#volume","id":"3jqRDwAAQBAJ","etag":"yzYes7YScsM","selfLink":"https://www.googleapis.com/books/v1/volumes/3jqRDwAAQBAJ","volumeInfo":{"title":"jap形容詞研究入門. 下","authors":["湯廷池編著"],"publisher":"致良","publishedDate":"2012-01-01","description":"內容簡介： 本書全書以日文編寫。 本書分為上下冊，下冊內容為：「日本語?形容詞化接尾?」、「形容詞?名詞化接尾?」、「形容名詞化接尾?」、「日本語形容詞?動詞化接尾?」、「日本語形容詞?形容名詞?接頭?」、「日本語形容詞?形容名詞?複合語」、「日本語??????型?捉?方?教?方」、「日本語?『多重主格』形容詞述語文」，並附有術語對照索引，適合對日語語言學有進一步興趣者、研究日語語言學的專業人士作參考。 作者1931年生於台灣苗栗縣，留學美國德州大學奧斯汀分校，1972年獲語言學博士學位。先後任教於台灣師大、清大、元智、交大、輔大及新竹教育大學等，並在東吳大學日文學系任客座教授，與輔仁大學外語學院野聲講座教授。","industryIdentifiers":[{"type":"ISBN_13","identifier":"9789577866813"},{"type":"ISBN_10","identifier":"9577866816"}],"readingModes":{"text":false,"image":true},"pageCount":390,"printType":"BOOK","categories":["Foreign Language Study"],"maturityRating":"NOT_MATURE","allowAnonLogging":false,"contentVersion":"0.1.0.0.preview.1","panelizationSummary":{"containsEpubBubbles":false,"containsImageBubbles":false},"imageLinks":{"smallThumbnail":"http://books.google.com/books/content?id=3jqRDwAAQBAJ&printsec=frontcover&img=1&zoom=5&edge=curl&source=gbs_api","thumbnail":"http://books.google.com/books/content?id=3jqRDwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api"},"language":"zh-CN","previewLink":"http://books.google.co.jp/books?id=3jqRDwAAQBAJ&pg=PA302&dq=%E3%81%AA&hl=&cd=3&source=gbs_api","infoLink":"https://play.google.com/store/books/details?id=3jqRDwAAQBAJ&source=gbs_api","canonicalVolumeLink":"https://play.google.com/store/books/details?id=3jqRDwAAQBAJ"},"saleInfo":{"country":"JP","saleability":"FOR_SALE","isEbook":true,"listPrice":{"amount":1499,"currencyCode":"JPY"},"retailPrice":{"amount":1349,"currencyCode":"JPY"},"buyLink":"https://play.google.com/store/books/details?id=3jqRDwAAQBAJ&rdid=book-3jqRDwAAQBAJ&rdot=1&source=gbs_api","offers":[{"finskyOfferType":1,"listPrice":{"amountInMicros":1499000000,"currencyCode":"JPY"},"retailPri