INSERT INTO google_book values ("52m3DwAAQBAJ", "龍馬、蝦夷に征く！ （下）", '{"kind":"books#volume","id":"52m3DwAAQBAJ","etag":"ddRdU5x1Z0w","selfLink":"https://www.googleapis.com/books/v1/volumes/52m3DwAAQBAJ","volumeInfo":{"title":"龍馬、蝦夷に征く！ （下）","authors":["ナリタマサヒロ"],"publisher":"マイナビ出版","publishedDate":"2015-09-30","description":"潜水艦4隻、乗組員2,000人を率いて箱館戦争に現れた坂本龍馬は、土方歳三と榎本武揚を前にして、自ら命をかけて実現した大政奉還、師である勝海舟、盟友西郷隆盛、そしてかつて実現に向けて奔走した蝦夷地開拓への想いを語る。しかし、遠く鹿児島の地では、私学校が暴発しかけていた……。","industryIdentifiers":[{"type":"OTHER","identifier":"PKEY:BT000033925900200201900209"}],"readingModes":{"text":true,"image":true},"pageCount":26,"printType":"BOOK","categories":["Fiction"],"maturityRating":"NOT_MATURE","allowAnonLogging":false,"contentVersion":"1.2.4.0.preview.3","panelizationSummary":{"containsEpubBubbles":false,"containsImageBubbles":false},"imageLinks":{"smallThumbnail":"http://books.google.com/books/content?id=52m3DwAAQBAJ&printsec=frontcover&img=1&zoom=5&edge=curl&source=gbs_api","thumbnail":"http://books.google.com/books/content?id=52m3DwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api"},"language":"ja","previewLink":"http://books.google.co.jp/books?id=52m3DwAAQBAJ&pg=PA3&dq=%E3%81%AB&hl=&cd=7&source=gbs_api","infoLink":"https://play.google.com/store/books/details?id=52m3DwAAQBAJ&source=gbs_api","canonicalVolumeLink":"https://play.google.com/store/books/details?id=52m3DwAAQBAJ"},"saleInfo":{"country":"JP","saleability":"FOR_SALE","isEbook":true,"listPrice":{"amount":550,"currencyCode":"JPY"},"retailPrice":{"amount":495,"currencyCode":"JPY"},"buyLink":"https://play.google.com/store/books/details?id=52m3DwAAQBAJ&rdid=book-52m3DwAAQBAJ&rdot=1&source=gbs_api","offers":[{"finskyOfferType":1,"listPrice":{"amountInMicros":550000000,"currencyCode":"JPY"},"retailPrice":{"amountInMicros":495000000,"currencyCode":"JPY"}}]},"accessInfo":{"country":"JP","viewability":"PARTIAL","embeddable":true,"publicDomain":false,"textToSpeechPermission":"ALLOWED","epub":{"isAvailable":true,"acsToken