INSERT INTO google_book values ("zfViDQAAQBAJ", "包丁無宿 25", '{"kind":"books#volume","id":"zfViDQAAQBAJ","etag":"3OfbLELUtu0","selfLink":"https://www.googleapis.com/books/v1/volumes/zfViDQAAQBAJ","volumeInfo":{"title":"包丁無宿 25","authors":["たがわ靖之"],"publisher":"日本文芸社","description":"賭け料理専門の料理人・阿修羅（あしゅら）の兄弟を見かけた暮流助（くれ・りゅうすけ）。五條屋に雇われた兄弟の目的は明神屋で働く女板前と知った暮は、その後を追って元黒包丁の紅（くれない）と再会する。そして、暮と紅なら阿修羅の兄弟に勝てると考えた明神屋の主人が、店を賭けた料理勝負を受ける。しかし、暮は勝負を断り、紅が一人で勝負を……!?","industryIdentifiers":[{"type":"OTHER","identifier":"PKEY:BT000023723102502501900209"}],"readingModes":{"text":true,"image":true},"pageCount":211,"printType":"BOOK","categories":["Comics & Graphic Novels"],"maturityRating":"NOT_MATURE","allowAnonLogging":true,"contentVersion":"1.3.0.0.preview.3","panelizationSummary":{"containsEpubBubbles":true,"containsImageBubbles":true,"epubBubbleVersion":"4c944e1abf51abce_A","imageBubbleVersion":"4c944e1abf51abce_A"},"imageLinks":{"smallThumbnail":"http://books.google.com/books/content?id=zfViDQAAQBAJ&printsec=frontcover&img=1&zoom=5&edge=curl&source=gbs_api","thumbnail":"http://books.google.com/books/content?id=zfViDQAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api"},"language":"ja","previewLink":"http://books.google.co.jp/books?id=zfViDQAAQBAJ&pg=PA151&dq=%E3%81%AC&hl=&cd=1&source=gbs_api","infoLink":"https://play.google.com/store/books/details?id=zfViDQAAQBAJ&source=gbs_api","canonicalVolumeLink":"https://play.google.com/store/books/details?id=zfViDQAAQBAJ","seriesInfo":{"kind":"books#volume_series_info","bookDisplayNumber":"25","volumeSeries":[{"seriesId":"jPf3GgAAABB67M","seriesBookType":"COLLECTED_EDITION","orderNumber":25}]}},"saleInfo":{"country":"JP","saleability":"FOR_SALE","isEbook":true,"listPrice":{"amount":533,"currencyCode":"JPY"},"retailPrice":{"amount":480,"currencyCode":"JPY"},"buyLink":"https://play.google.com/store/books/details?id=zfViDQAAQBAJ&rdid=book-zfViDQAAQBAJ&rdot=1&source=gbs_api","offers":[{"finskyOfferType":1,"listPrice":{"amountInMicros":533