INSERT INTO google_book values ("N9WmEAAAQBAJ", "Final名字電子字典【な行】", '{"kind":"books#volume","id":"N9WmEAAAQBAJ","etag":"pdV5zv9GZns","selfLink":"https://www.googleapis.com/books/v1/volumes/N9WmEAAAQBAJ","volumeInfo":{"title":"Final名字電子字典【な行】","subtitle":"日本の名字【な～のんばら】","authors":["h.k"],"publisher":"ビーコンセプト","publishedDate":"2023-01-11","description":"日本の名字『な～のんばら』までを外字を含む名字を収録しています。 収録されている名字(外字を含む)はＩＰＡmj明朝にも収録されています。 ※一部ＩＰＡmj明朝には未収録な文字があります","readingModes":{"text":false,"image":true},"pageCount":94,"printType":"BOOK","categories":["Foreign Language Study"],"maturityRating":"NOT_MATURE","allowAnonLogging":false,"contentVersion":"0.1.0.0.preview.1","panelizationSummary":{"containsEpubBubbles":false,"containsImageBubbles":false},"imageLinks":{"smallThumbnail":"http://books.google.com/books/content?id=N9WmEAAAQBAJ&printsec=frontcover&img=1&zoom=5&edge=curl&source=gbs_api","thumbnail":"http://books.google.com/books/content?id=N9WmEAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api"},"language":"ja","previewLink":"http://books.google.co.jp/books?id=N9WmEAAAQBAJ&pg=PA966&dq=%E3%81%AC&hl=&cd=2&source=gbs_api","infoLink":"https://play.google.com/store/books/details?id=N9WmEAAAQBAJ&source=gbs_api","canonicalVolumeLink":"https://play.google.com/store/books/details?id=N9WmEAAAQBAJ"},"saleInfo":{"country":"JP","saleability":"FOR_SALE","isEbook":true,"listPrice":{"amount":1210,"currencyCode":"JPY"},"retailPrice":{"amount":1089,"currencyCode":"JPY"},"buyLink":"https://play.google.com/store/books/details?id=N9WmEAAAQBAJ&rdid=book-N9WmEAAAQBAJ&rdot=1&source=gbs_api","offers":[{"finskyOfferType":1,"listPrice":{"amountInMicros":1210000000,"currencyCode":"JPY"},"retailPrice":{"amountInMicros":1089000000,"currencyCode":"JPY"}}]},"accessInfo":{"country":"JP","viewability":"PARTIAL","embeddable":true,"publicDomain":false,"textToSpeechPermission":"ALLOWED","epub":{"isAvailable":false},"pdf":{"isAvailable":true,"acsTokenLink":"http://books.google.co.jp/books/download/Final%E