INSERT INTO google_book values ("002CGFGEdDMC", "Intermediate Technical Japanese, Volume 1", '{"kind":"books#volume","id":"002CGFGEdDMC","etag":"/Yr8w1Pm/U8","selfLink":"https://www.googleapis.com/books/v1/volumes/002CGFGEdDMC","volumeInfo":{"title":"Intermediate Technical Japanese, Volume 1","subtitle":"Readings and Grammatical Patterns","authors":["James L. Davis"],"publisher":"Univ of Wisconsin Press","publishedDate":"2002-12-01","description":"Learn how to read and translate technical manuals, research publications, and reference works. This two-volume set is designed to help the intermediate-level learner of Japanese build a technical vocabulary, reinforce understanding of frequently used grammatical patterns, improve reading comprehension, and practice translating technical passages. The glossary in volume 2 clarifies words and phrases that often puzzle beginning readers. The sample readings on technical topics are drawn from a broad range of specialties, from mathematics and computer science to electronics and polymer science. The initial grammar lesson and the first nine field-specific lessons constitute the common core to be used by all instructors or students. Topics of interest from the remaining thirty-one field-specific lessons may be selected to produce a customized course of study. Intermediate Technical Japanese is designed to fulfill a typical two-semester sequence. Volume 1 contains: o information about 600 key kanji o explanations of 100 important grammatical patterns o more than 700 scientific or technical essays o an index of the grammatical patterns. Volume 2 contains: o a complete glossary","industryIdentifiers":[{"type":"ISBN_13","identifier":"9780299185534"},{"type":"ISBN_10","identifier":"0299185532"}],"readingModes":{"text":false,"image":true},"pageCount":495,"printType":"BOOK","categories":["Foreign Language Study"],"maturityRating":"NOT_MATURE","allowAnonLogging":true,"contentVersion":"0.4.0.0.preview.1","panelizationSummary":{"containsE