INSERT INTO google_book values ("55dnDwAAQBAJ", "英語とはどんな言語か — より深く英語を知るために —", '{"kind":"books#volume","id":"55dnDwAAQBAJ","etag":"1ZSkzwnALEU","selfLink":"https://www.googleapis.com/books/v1/volumes/55dnDwAAQBAJ","volumeInfo":{"title":"英語とはどんな言語か — より深く英語を知るために —","authors":["安井稔"],"publisher":"開拓社","publishedDate":"2014-03-28","description":"英語学習の実が上がらないのは、英語を易しいほうに見誤っていることに大きな原因がある、と著者は主張する。英語を身につけるためには、なによりも英語という言語の「くせ」を知る必要があるとの考えに立ち、気むずかしそうな綴りや文法にひそむ性質を明らかにし、加えて、英語をなだらかに使えるようにする表現や心得の数々を盛り込んで、英語とのよりよいつき合い方を教えてくれる一冊。 ※紙版とは一部、内容が異なります。","industryIdentifiers":[{"type":"OTHER","identifier":"PKEY:CYZOJGP0000000000221"}],"readingModes":{"text":true,"image":true},"pageCount":131,"printType":"BOOK","categories":["Foreign Language Study"],"maturityRating":"NOT_MATURE","allowAnonLogging":false,"contentVersion":"1.4.4.0.preview.3","panelizationSummary":{"containsEpubBubbles":false,"containsImageBubbles":false},"imageLinks":{"smallThumbnail":"http://books.google.com/books/content?id=55dnDwAAQBAJ&printsec=frontcover&img=1&zoom=5&edge=curl&source=gbs_api","thumbnail":"http://books.google.com/books/content?id=55dnDwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api"},"language":"ja","previewLink":"http://books.google.co.jp/books?id=55dnDwAAQBAJ&pg=PT6&dq=%E3%81%AF&hl=&cd=1&source=gbs_api","infoLink":"https://play.google.com/store/books/details?id=55dnDwAAQBAJ&source=gbs_api","canonicalVolumeLink":"https://play.google.com/store/books/details?id=55dnDwAAQBAJ"},"saleInfo":{"country":"JP","saleability":"FOR_SALE","isEbook":true,"listPrice":{"amount":2090,"currencyCode":"JPY"},"retailPrice":{"amount":1881,"currencyCode":"JPY"},"buyLink":"https://play.google.com/store/books/details?id=55dnDwAAQBAJ&rdid=book-55dnDwAAQBAJ&rdot=1&source=gbs_api","offers":[{"finskyOfferType":1,"listPrice":{"amountInMicros":2090000000,"currencyCode":"JPY"},"retailPrice":{"amountInMicros":1881000000,"currencyCode":"JPY"}}]},"accessInfo":{"country":"JP","viewability":"PARTIAL","embeddable":