INSERT INTO google_book values ("d4PuAgAAQBAJ", "信長殺しは、秀吉か", '{"kind":"books#volume","id":"d4PuAgAAQBAJ","etag":"59+kJWcyPJI","selfLink":"https://www.googleapis.com/books/v1/volumes/d4PuAgAAQBAJ","volumeInfo":{"title":"信長殺しは、秀吉か","authors":["八切止夫"],"publisher":"作品社（インプレス）","publishedDate":"2014-02-27","description":"織田信長の生前、豊臣秀吉は毛利と和睦していた! 信長を殺した犯人は秀吉なのか-。信長の弟・織田有楽を探偵役として小説形式でこの疑惑の真相に挑む。 ーー戦後の歴史小説界で異彩を放った伝説の奇才・八切止夫。古代から幕末までの2000年有余の日本史の謎に果敢に挑み、大胆な着想、膨大な資料の渉猟、比類なき想像力によって、既成の通説を次々と覆したその独自の歴史観は「八切史観」と呼ばれる。","readingModes":{"text":true,"image":true},"pageCount":260,"printType":"BOOK","categories":["History"],"maturityRating":"NOT_MATURE","allowAnonLogging":true,"contentVersion":"1.1.3.0.preview.3","panelizationSummary":{"containsEpubBubbles":false,"containsImageBubbles":false},"imageLinks":{"smallThumbnail":"http://books.google.com/books/content?id=d4PuAgAAQBAJ&printsec=frontcover&img=1&zoom=5&edge=curl&source=gbs_api","thumbnail":"http://books.google.com/books/content?id=d4PuAgAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api"},"language":"ja","previewLink":"http://books.google.co.jp/books?id=d4PuAgAAQBAJ&pg=PT89&dq=%E3%81%AF&hl=&cd=2&source=gbs_api","infoLink":"http://books.google.co.jp/books?id=d4PuAgAAQBAJ&dq=%E3%81%AF&hl=&source=gbs_api","canonicalVolumeLink":"https://books.google.com/books/about/%E4%BF%A1%E9%95%B7%E6%AE%BA%E3%81%97%E3%81%AF_%E7%A7%80%E5%90%89%E3%81%8B.html?hl=&id=d4PuAgAAQBAJ"},"saleInfo":{"country":"JP","saleability":"NOT_FOR_SALE","isEbook":false},"accessInfo":{"country":"JP","viewability":"PARTIAL","embeddable":true,"publicDomain":false,"textToSpeechPermission":"ALLOWED","epub":{"isAvailable":true,"acsTokenLink":"http://books.google.co.jp/books/download/%E4%BF%A1%E9%95%B7%E6%AE%BA%E3%81%97%E3%81%AF_%E7%A7%80%E5%90%89%E3%81%8B-sample-epub.acsm?id=d4PuAgAAQBAJ&format=epub&output=acs4_fulfillment_token&dl_type=sample&source=gbs_api"},"pdf":{"isAvailable":true,"acsTokenLink":"http://books.google.co.jp/books/download/%E4%BF%A1%E9%95%B