INSERT INTO google_book values ("rS9-DQAAQBAJ", "皇帝陛下は逃がさない", '{"kind":"books#volume","id":"rS9-DQAAQBAJ","etag":"BG5Gqi9j/ks","selfLink":"https://www.googleapis.com/books/v1/volumes/rS9-DQAAQBAJ","volumeInfo":{"title":"皇帝陛下は逃がさない","authors":["山野辺りり","五十鈴"],"publisher":"イースト・プレス","publishedDate":"2014-07-08","description":"もっと君を可愛がりたい。 小国の末姫シシーナのもとに突然届いた結婚の申込み。相手はなんと、冷血で残虐と噂される大国の皇帝レオハルト。攫われるように彼のもとへ嫁いだシシーナだったが、豪華な鳥籠に閉じ込められて……！？ どうして私をこんなところに？ 理由を聞こうとしてもはぐらかされ、甘い言葉と執拗な愛撫で彼の手管に呑まれてしまう。身体だけじゃなくて心も通じ合いたいのに――。そう悩んでいた矢先、とある事件に巻き込まれ……？","industryIdentifiers":[{"type":"OTHER","identifier":"PKEY:BT000027909700100101900209"}],"readingModes":{"text":true,"image":true},"pageCount":114,"printType":"BOOK","categories":["Fiction"],"maturityRating":"MATURE","allowAnonLogging":true,"contentVersion":"1.4.6.0.preview.3","panelizationSummary":{"containsEpubBubbles":false,"containsImageBubbles":false},"imageLinks":{"smallThumbnail":"http://books.google.com/books/content?id=rS9-DQAAQBAJ&printsec=frontcover&img=1&zoom=5&edge=curl&source=gbs_api","thumbnail":"http://books.google.com/books/content?id=rS9-DQAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api"},"language":"ja","previewLink":"http://books.google.co.jp/books?id=rS9-DQAAQBAJ&pg=PT50&dq=%E3%81%AF&hl=&cd=3&source=gbs_api","infoLink":"https://play.google.com/store/books/details?id=rS9-DQAAQBAJ&source=gbs_api","canonicalVolumeLink":"https://play.google.com/store/books/details?id=rS9-DQAAQBAJ"},"saleInfo":{"country":"JP","saleability":"FOR_SALE","isEbook":true,"listPrice":{"amount":660,"currencyCode":"JPY"},"retailPrice":{"amount":594,"currencyCode":"JPY"},"buyLink":"https://play.google.com/store/books/details?id=rS9-DQAAQBAJ&rdid=book-rS9-DQAAQBAJ&rdot=1&source=gbs_api","offers":[{"finskyOfferType":1,"listPrice":{"amountInMicros":660000000,"currencyCode":"JPY"},"retailPrice":{"amountInMicros":594000000,"currencyCode":"JPY"}}]},"accessInfo":{"country":"JP","viewability":"PARTIAL","embeddable":true,"publicDomain":false,"textToSpeechPermission":"ALLOWED","epub":{"isAvailable":true,"acsTokenLink":"http://books.google.co.jp/books/download/%E7%9A%87%E5%B8%9D%E9%99%9B%E4%B8%8B%E3%81%AF%E9%80%83%E3%81%8C%E3%81%95%E3%81%AA%E3%81%84-sample-epub.acsm?id=rS9-DQAAQBAJ&format=epub&output=acs4_fulfillment_token&dl_type=sample&source=gbs_api"},"pdf":{"isAvailable":true,"acsTokenLink":"http://books.google.co.jp/books/download/%E7%9A%87%E5%B8%9D%E9%99%9B%E4%B8%8B%E3%81%AF%E9%80%83%E3%81%8C%E3%81%95%E3%81%AA%E3%81%84-sample-pdf.acsm?id=rS9-DQAAQBAJ&format=pdf&output=acs4_fulfillment_token&dl_type=sample&source=gbs_api"},"webReaderLink":"http://play.google.com/books/reader?id=rS9-DQAAQBAJ&hl=&source=gbs_api","accessViewStatus":"SAMPLE","quoteSharingAllowed":false},"searchInfo":{"textSnippet":"... <b>ハ</b>てかさぎ」にもバうあ余器らで心ナど自ルいかれ檻ナさそレいる計に、い旺<b>は</b>分トなわずにのれのシっ階なつまた盛茶会、ですか」外に、出られる。奇心皿なシシーナ<b>は</b>学ぶことが嫌いではない。元々オールロにいた頃から、女に<b>は</b>不要とされている兵法まで&nbsp;..."}}');
INSERT INTO google_book values ("2DFwDwAAQBAJ", "経営は人づくりにあり", '{"kind":"books#volume","id":"2DFwDwAAQBAJ","etag":"cKozMX5wajo","selfLink":"https://www.googleapis.com/books/v1/volumes/2DFwDwAAQBAJ","volumeInfo":{"title":"経営は人づくりにあり","subtitle":"日立ソフト・成功の秘密","authors":["中村嘉人"],"publisher":"PHP研究所","publishedDate":"2002-03-15","description":"日立ソフトウェアエンジニアリング株式会社は、不況の中、着実に伸びている超優良企業である。本書は、二代目社長として登板し、東証一部に上場させたうえ、親会社を超える実績をあげつづけている現会長・佐藤孜の半生をつづりながら、氏の人生観や経営に対する考え方を浮き彫りにするとともに、成功の秘密を説き明かした一冊である。著者である中村嘉人氏は、佐藤孜氏の旧制弘前高校仲間であり、佐藤氏のベースはその時代に育まれたという。弘前時代の様々なエピソードや人々との交流を小説仕立てで描きながら、氏の東北人ならではの粘り強い性格や、ひたむきに物事に取り組む姿を映し出す。また、日立ソフト時代におこったさまざまな難題や課題をどのように乗り越えてきたのかについて、佐藤氏を支える日立ソフト社員の奮闘ぶりとともに活写している。本書には、単に事業成功のノウハウだけでなく、ビジネスマンとしての生き方のヒントが隠されている！ 【PHP研究所】","industryIdentifiers":[{"type":"OTHER","identifier":"PKEY:56962097210090610003"}],"readingModes":{"text":true,"image":true},"pageCount":184,"printType":"BOOK","categories":["Business & Economics"],"maturityRating":"NOT_MATURE","allowAnonLogging":false,"contentVersion":"1.3.4.0.preview.3","panelizationSummary":{"containsEpubBubbles":false,"containsImageBubbles":false},"imageLinks":{"smallThumbnail":"http://books.google.com/books/content?id=2DFwDwAAQBAJ&printsec=frontcover&img=1&zoom=5&edge=curl&source=gbs_api","thumbnail":"http://books.google.com/books/content?id=2DFwDwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api"},"language":"ja","previewLink":"http://books.google.co.jp/books?id=2DFwDwAAQBAJ&pg=PT137&dq=%E3%81%AF&hl=&cd=4&source=gbs_api","infoLink":"https://play.google.com/store/books/details?id=2DFwDwAAQBAJ&source=gbs_api","canonicalVolumeLink":"https://play.google.com/store/books/details?id=2DFwDwAAQBAJ"},"saleInfo":{"country":"JP","saleability":"FOR_SALE","isEbook":true,"listPrice":{"amount":1500,"currencyCode":"JPY"},"retailPrice":{"amount":1350,"currencyCode":"JPY"},"buyLink":"https://play.google.com/store/books/details?id=2DFwDwAAQBAJ&rdid=book-2DFwDwAAQBAJ&rdot=1&source=gbs_api","offers":[{"finskyOfferTyp