INSERT INTO google_book values ("TPxTDwAAQBAJ", "私家版　和語辞典　増補版", '{"kind":"books#volume","id":"TPxTDwAAQBAJ","etag":"3qcjXKqhoHg","selfLink":"https://www.googleapis.com/books/v1/volumes/TPxTDwAAQBAJ","volumeInfo":{"title":"私家版　和語辞典　増補版","authors":["足立晋"],"publisher":"デジタルパブリッシングサービス","publishedDate":"2018-04-05","description":"※この商品はタブレットなど大きいディスプレイを備えた端末で読むことに適しています。また、文字だけを拡大することや、文字列のハイライト、検索、辞書の参照、引用などの機能が使用できません。 和語には「め（目）」のような一拍語から「見る」「見える」「見られる」など長短さまざまな語がある。著者は、和語は大昔は一拍や二拍の短小語で時代の経過につれて長語化したという事実をつきとめた。またひとつひとつの語はそれを構成する子音が根本的な意味をもち、同じ子音をもつ語どうしは同じような意味をもつ語のグループを形成することも見出した。国語学のこの分野にはじめて確たる方法論をもたらしたと言えるであろう。","industryIdentifiers":[{"type":"OTHER","identifier":"PKEY:BT000051114300100101900209"}],"readingModes":{"text":true,"image":true},"pageCount":491,"printType":"BOOK","categories":["Reference"],"maturityRating":"NOT_MATURE","allowAnonLogging":false,"contentVersion":"1.4.2.0.preview.3","panelizationSummary":{"containsEpubBubbles":false,"containsImageBubbles":false},"imageLinks":{"smallThumbnail":"http://books.google.com/books/content?id=TPxTDwAAQBAJ&printsec=frontcover&img=1&zoom=5&edge=curl&source=gbs_api","thumbnail":"http://books.google.com/books/content?id=TPxTDwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api"},"language":"ja","previewLink":"http://books.google.co.jp/books?id=TPxTDwAAQBAJ&pg=PA354&dq=%E3%81%BB&hl=&cd=5&source=gbs_api","infoLink":"http://books.google.co.jp/books?id=TPxTDwAAQBAJ&dq=%E3%81%BB&hl=&source=gbs_api","canonicalVolumeLink":"https://books.google.com/books/about/%E7%A7%81%E5%AE%B6%E7%89%88_%E5%92%8C%E8%AA%9E%E8%BE%9E%E5%85%B8_%E5%A2%97%E8%A3%9C%E7%89%88.html?hl=&id=TPxTDwAAQBAJ"},"saleInfo":{"country":"JP","saleability":"NOT_FOR_SALE","isEbook":false},"accessInfo":{"country":"JP","viewability":"PARTIAL","embeddable":true,"publicDomain":false,"textToSpeechPermission":"ALLOWED","epub":{"isAvailable":true,"acsTokenLink":"http://books.google.co.jp/books/download/%E7%A7%81%E5%AE%B6%E7%89%88_%E5%92%8C%E8%AA%9E%E8%BE%9E%E