INSERT INTO google_book values ("yidwDQAAQBAJ", "Rock Soul - Tome 1 - Apparition", '{"kind":"books#volume","id":"yidwDQAAQBAJ","etag":"qAeGgJbm1Ko","selfLink":"https://www.googleapis.com/books/v1/volumes/yidwDQAAQBAJ","volumeInfo":{"title":"Rock Soul - Tome 1 - Apparition","authors":["Luana Vergari"],"publisher":"Jungle","publishedDate":"2016-11-04T00:00:00+01:00","description":"Après la mort de sa mère, la jeune Olivia part vivre avec son grand père qu’elle connait peu. Une nouvelle vie de famille qui s’annoncera difficile... Pour lui changer les idées, son grand-père lui propose de travailler dans son magasin de disques : le Pink Mellow. Un lundi après-midi, Olivia rencontre le mystérieux « Vincent ONVI Dorothy » à la boutique de disques. Intriguée par cet homme, Olivia va mener l’enquête et réaliser que « Vincent ONVI Dorothy » est en réalité est un chanteur décédé depuis des années... Que fait-il alors au milieu des vivants ? Pourquoi peut-elle le voir ? Et surtout : que lui veut-il ? De nombreux mystères sur lesquels Olivia va peu à peu lever le voile.","industryIdentifiers":[{"type":"ISBN_13","identifier":"9782822216135"},{"type":"ISBN_10","identifier":"2822216134"}],"readingModes":{"text":true,"image":true},"pageCount":51,"printType":"BOOK","categories":["Comics & Graphic Novels"],"maturityRating":"NOT_MATURE","allowAnonLogging":false,"contentVersion":"1.1.1.0.preview.3","panelizationSummary":{"containsEpubBubbles":false,"containsImageBubbles":false},"imageLinks":{"smallThumbnail":"http://books.google.com/books/content?id=yidwDQAAQBAJ&printsec=frontcover&img=1&zoom=5&edge=curl&source=gbs_api","thumbnail":"http://books.google.com/books/content?id=yidwDQAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api"},"language":"fr","previewLink":"http://books.google.co.jp/books?id=yidwDQAAQBAJ&pg=PT5&dq=%E3%82%89&hl=&cd=3&source=gbs_api","infoLink":"http://books.google.co.jp/books?id=yidwDQAAQBAJ&dq=%E3%82%89&hl=&source=gbs_api","canonicalVolumeLink":"https: