INSERT INTO google_book values ("wVmcEQAAQBAJ", "読書と思索", '{"kind":"books#volume","id":"wVmcEQAAQBAJ","etag":"V6e8xI1+9kE","selfLink":"https://www.googleapis.com/books/v1/volumes/wVmcEQAAQBAJ","volumeInfo":{"title":"読書と思索","authors":["田中美知太郎"],"publisher":"第三文明社","publishedDate":"2025-12-11","description":"ギリシャ哲学研究の第一人者・田中美知太郎（京都大学名誉教授）が遺した、読書と思索にまつわる数々のエッセイがいま蘇る。没後40年を迎え、新装版として復刊。 自己論・読書論・教養論の三部からなる本書は、戦前から戦後にかけて著者が己の人生と知の軌跡を語った、稀有な告白の書である。論考の行間には、時代と真摯に向き合いながら思索を深めた一人の哲学者の人間像が浮かび上がる。重厚な学問の背後に息づく「思索する魂」に触れることのできる一冊。 「一時的の涙や笑いを、書物から受動的に受け取ろうとするのではなくて、自分の全心を能動的にはたらかせて、一見冷やかに、親しみ難く思われるような言葉の奥に、人間のあたたかくて、親切な心を探り出すというのも、また大切な読書のよろこびであることを知ってもらいたいように思う。」――本文より。","industryIdentifiers":[{"type":"OTHER","identifier":"PKEY:BT000209291600100101900209"}],"readingModes":{"text":true,"image":true},"pageCount":69,"printType":"BOOK","categories":["Philosophy"],"maturityRating":"NOT_MATURE","allowAnonLogging":false,"contentVersion":"0.1.1.0.preview.3","panelizationSummary":{"containsEpubBubbles":false,"containsImageBubbles":false},"imageLinks":{"smallThumbnail":"http://books.google.com/books/content?id=wVmcEQAAQBAJ&printsec=frontcover&img=1&zoom=5&edge=curl&source=gbs_api","thumbnail":"http://books.google.com/books/content?id=wVmcEQAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api"},"language":"ja","previewLink":"http://books.google.co.jp/books?id=wVmcEQAAQBAJ&pg=PT13&dq=%E3%82%8B&hl=&cd=1&source=gbs_api","infoLink":"https://play.google.com/store/books/details?id=wVmcEQAAQBAJ&source=gbs_api","canonicalVolumeLink":"https://play.google.com/store/books/details?id=wVmcEQAAQBAJ"},"saleInfo":{"country":"JP","saleability":"FOR_SALE","isEbook":true,"listPrice":{"amount":1375,"currencyCode":"JPY"},"retailPrice":{"amount":1238,"currencyCode":"JPY"},"buyLink":"https://play.google.com/store/books/details?id=wVmcEQAAQBAJ&rdid=book-wVmcEQAAQBAJ&rdot=1&source=gbs_api","offers":[{"finskyOfferType":1,"listPrice":{"amountInMicros":1375000000,"currencyCode":"JPY"},"retailPrice":{"amount