INSERT INTO google_book values ("NQSDDwAAQBAJ", "世界の哲学 50の名著 エッセンスを究める", '{"kind":"books#volume","id":"NQSDDwAAQBAJ","etag":"ljEaGFPY7Ws","selfLink":"https://www.googleapis.com/books/v1/volumes/NQSDDwAAQBAJ","volumeInfo":{"title":"世界の哲学 50の名著 エッセンスを究める","authors":["T・バトラー=ボードン","大間知知子"],"publisher":"ディスカヴァー・トゥエンティワン","publishedDate":"2014-02-21","description":"プラトン、アリストテレスなどの古代の哲学者、 パスカル、ハイデガー、カント、ヘーゲル、ニーチェなどの近代の哲学者、 そしてマイケル・サンデル・スラヴォイ・ジジェク、ピーター・シンガーなどの現代の思想家まで、 古今東西の代表的哲学者の名著５０冊のエッセンスがこの１冊にまとまりました。 「可能性の文学の真の研究者」（USAトゥデイ紙）とも批評される著者T.バトラー=ボードンは、 「人生の道案内」として、また「世界の本質を照らす光」として哲学を活用する方法を提案しています。 英語版のみで累計３０万部、世界２３言語に翻訳される世界的ロング＆ベストセラーシリーズの最新刊。","industryIdentifiers":[{"type":"OTHER","identifier":"PKEY:BT000025046000100101900206"}],"readingModes":{"text":true,"image":true},"pageCount":295,"printType":"BOOK","categories":["Philosophy"],"maturityRating":"NOT_MATURE","allowAnonLogging":false,"contentVersion":"1.2.4.0.preview.3","panelizationSummary":{"containsEpubBubbles":false,"containsImageBubbles":false},"imageLinks":{"smallThumbnail":"http://books.google.com/books/content?id=NQSDDwAAQBAJ&printsec=frontcover&img=1&zoom=5&edge=curl&source=gbs_api","thumbnail":"http://books.google.com/books/content?id=NQSDDwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api"},"language":"ja","previewLink":"http://books.google.co.jp/books?id=NQSDDwAAQBAJ&pg=PT11&dq=%E3%82%8B&hl=&cd=5&source=gbs_api","infoLink":"https://play.google.com/store/books/details?id=NQSDDwAAQBAJ&source=gbs_api","canonicalVolumeLink":"https://play.google.com/store/books/details?id=NQSDDwAAQBAJ"},"saleInfo":{"country":"JP","saleability":"FOR_SALE","isEbook":true,"listPrice":{"amount":2420,"currencyCode":"JPY"},"retailPrice":{"amount":2178,"currencyCode":"JPY"},"buyLink":"https://play.google.com/store/books/details?id=NQSDDwAAQBAJ&rdid=book-NQSDDwAAQBAJ&rdot=1&source=gbs_api","offers":[{"finskyOfferType":1,"listPrice":{"amountInMicros":2420000000,"currencyCode":"JPY"},"retailPrice":{"amountInMicros":21780