INSERT INTO google_book values ("1hY3DwAAQBAJ", "常世桜　地神盲僧、妖ヲ謡フ", '{"kind":"books#volume","id":"1hY3DwAAQBAJ","etag":"7JV27VJedeg","selfLink":"https://www.googleapis.com/books/v1/volumes/1hY3DwAAQBAJ","volumeInfo":{"title":"常世桜　地神盲僧、妖ヲ謡フ","authors":["加門七海"],"publisher":"アドレナライズ","publishedDate":"2017-09-07","description":"どこにでも異界はひっそりと口を開け、いつでも世界はどこかしら汚濁にまみれている。桜の古木の傍らに小さな庵を営んで、十六夜清玄は訪れるものを静かに待っている。笹琵琶を掻き鳴らし、経文を唱え、世界の律呂をととのえようと…。三宝荒神の力を頼み、姿無き神霊・精霊と交感する清玄が“見た”ものは。怪奇幻想連作小説。 ●加門七海（かもん・ななみ） 東京都生まれ。オカルト・風水・民俗学などに造詣が深く、怪談、エッセイ、フィールドワーク作品などを著す。最新刊は『お咒い日和 その解説と実際』（KADOKAWA）。小説に『目嚢』『祝山』『鳥辺野にて』など、エッセイ『猫怪々』『霊能動物館』『墨東地霊散歩』など多数。","industryIdentifiers":[{"type":"OTHER","identifier":"PKEY:BT000046796000100101900209"}],"readingModes":{"text":true,"image":true},"pageCount":190,"printType":"BOOK","categories":["Fiction"],"maturityRating":"NOT_MATURE","allowAnonLogging":false,"contentVersion":"1.2.3.0.preview.3","panelizationSummary":{"containsEpubBubbles":false,"containsImageBubbles":false},"imageLinks":{"smallThumbnail":"http://books.google.com/books/content?id=1hY3DwAAQBAJ&printsec=frontcover&img=1&zoom=5&edge=curl&source=gbs_api","thumbnail":"http://books.google.com/books/content?id=1hY3DwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api"},"language":"ja","previewLink":"http://books.google.co.jp/books?id=1hY3DwAAQBAJ&pg=PT200&dq=%E3%82%92&hl=&cd=1&source=gbs_api","infoLink":"https://play.google.com/store/books/details?id=1hY3DwAAQBAJ&source=gbs_api","canonicalVolumeLink":"https://play.google.com/store/books/details?id=1hY3DwAAQBAJ"},"saleInfo":{"country":"JP","saleability":"FOR_SALE","isEbook":true,"listPrice":{"amount":770,"currencyCode":"JPY"},"retailPrice":{"amount":693,"currencyCode":"JPY"},"buyLink":"https://play.google.com/store/books/details?id=1hY3DwAAQBAJ&rdid=book-1hY3DwAAQBAJ&rdot=1&source=gbs_api","offers":[{"finskyOfferType":1,"listPrice":{"amountInMicros":770000000,"currencyCode":"JPY"},"retailPrice":{"amountInMicros":693000000,"currencyCode":"JPY"}}]},