INSERT INTO google_book values ("FhdFDQAAQBAJ", "Endotrivial modules over preprojective algebras", '{"kind":"books#volume","id":"FhdFDQAAQBAJ","etag":"wgPvodsyUnM","selfLink":"https://www.googleapis.com/books/v1/volumes/FhdFDQAAQBAJ","volumeInfo":{"title":"Endotrivial modules over preprojective algebras","authors":["Jakob Bongartz"],"publisher":"GRIN Verlag","publishedDate":"2016-07-01","description":"Master''s Thesis from the year 2015 in the subject Mathematics - Algebra, grade: 1,0, University of Bonn (Mathematisches Institut), language: English, abstract: Die Arbeit liefert eine abstrakt vollständige Klassifizierung endotrivialer Module über Präprojektiven Algebren von Dynkintypen ADE. Weiterhin gibt sie einen Ansatz für eine Verallgemeinerung. Weiterhin liefert sie einen Algorithmus um endotriviale Module zu konstruieren, deren Dimensionsvektoren positive Wurzeln sind. Für mehr Details verweisen wir auf die Einleitung der Arbeit.","industryIdentifiers":[{"type":"ISBN_13","identifier":"9783668251076"},{"type":"ISBN_10","identifier":"366825107X"}],"readingModes":{"text":false,"image":true},"pageCount":50,"printType":"BOOK","categories":["Mathematics"],"maturityRating":"NOT_MATURE","allowAnonLogging":false,"contentVersion":"0.3.0.0.preview.1","panelizationSummary":{"containsEpubBubbles":false,"containsImageBubbles":false},"imageLinks":{"smallThumbnail":"http://books.google.com/books/content?id=FhdFDQAAQBAJ&printsec=frontcover&img=1&zoom=5&edge=curl&source=gbs_api","thumbnail":"http://books.google.com/books/content?id=FhdFDQAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api"},"language":"en","previewLink":"http://books.google.co.jp/books?id=FhdFDQAAQBAJ&pg=PA6&dq=e&hl=&cd=10&source=gbs_api","infoLink":"https://play.google.com/store/books/details?id=FhdFDQAAQBAJ&source=gbs_api","canonicalVolumeLink":"https://play.google.com/store/books/details?id=FhdFDQAAQBAJ"},"saleInfo":{"country":"JP","saleability":"FOR_SALE","isEbook":true,"listPrice":{"amount":310