INSERT INTO google_book values ("iNqYS7LFQFYC", "G Protein Signaling", '{"kind":"books#volume","id":"iNqYS7LFQFYC","etag":"r4L3FqVgGF0","selfLink":"https://www.googleapis.com/books/v1/volumes/iNqYS7LFQFYC","volumeInfo":{"title":"G Protein Signaling","subtitle":"Methods and Protocols","authors":["Alan V. Smrcka"],"publisher":"Springer Science & Business Media","publishedDate":"2008-02-02","description":"Alan V. Smrcka presents a collection of cutting-edge methods for investigating G protein signaling from a variety of perspectives ranging from in vitro biochemistry to whole animal studies. Among the readily reproducible techniques presented are those for the purification of G proteins and effectors enzymes, assays of these purified G proteins and effector enzymes, and for the study of G proteins interactions with effectors in intact cells. Additional methods are provided for assaying G protein coupled receptor structure, function, and localization, and for studying the physiological roles for endogenous G proteins.","industryIdentifiers":[{"type":"ISBN_13","identifier":"9781592594306"},{"type":"ISBN_10","identifier":"1592594301"}],"readingModes":{"text":true,"image":true},"pageCount":246,"printType":"BOOK","categories":["Science"],"maturityRating":"NOT_MATURE","allowAnonLogging":false,"contentVersion":"1.3.5.0.preview.3","panelizationSummary":{"containsEpubBubbles":false,"containsImageBubbles":false},"imageLinks":{"smallThumbnail":"http://books.google.com/books/content?id=iNqYS7LFQFYC&printsec=frontcover&img=1&zoom=5&edge=curl&source=gbs_api","thumbnail":"http://books.google.com/books/content?id=iNqYS7LFQFYC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api"},"language":"en","previewLink":"http://books.google.co.jp/books?id=iNqYS7LFQFYC&pg=PA205&dq=g&hl=&cd=4&source=gbs_api","infoLink":"https://play.google.com/store/books/details?id=iNqYS7LFQFYC&source=gbs_api","canonicalVolumeLink":"https://play.google.com/store/books/details?id=iNqYS7LFQFYC"},"saleInfo":{"c