INSERT INTO google_book values ("CMPx-jksa6IC", "Watching M*A*S*H, Watching America", '{"kind":"books#volume","id":"CMPx-jksa6IC","etag":"C10s4U5qIa4","selfLink":"https://www.googleapis.com/books/v1/volumes/CMPx-jksa6IC","volumeInfo":{"title":"Watching M*A*S*H, Watching America","subtitle":"A Social History of the 1972-1983 Television Series","authors":["James H. Wittebols"],"publisher":"McFarland","publishedDate":"2003-06-19","description":"It has been said that M*A*S*H was a show set in the 1950s which reflected the shifting values of the 1970s and early 1980s. Hawkeye Pierce, Radar O''Reilly, Trapper John McIntyre, Sherman Potter, Margaret (Hot Lips) Houlihan, B.J. Hunnicutt, Frank Burns, Charles Emerson Winchester, Max Klinger--these and the many other characters who populated the MASH 4077 used the Korean War as a backdrop to comment on many of the social issues of their day. Using a unique blend of comedy and drama, the show''s first three seasons (1972-1975) focused on the anti-Vietnam War sentiment that consumed much of America. As Vietnam ended, M*A*S*H moved on to concentrate on other contemporary issues--the women''s movement, the rise of the religious right in American politics, the new narcissism that marked the early 1980s, the heightened awareness of underage or excessive alcohol use, and the increased emphasis on family in American life. How the series presented these issues and its success in doing so are the subjects of this critical study. An episode listing--brief plot outline, casts and credits, air dates, and titles--is also provided.","industryIdentifiers":[{"type":"ISBN_10","identifier":"0786417013"},{"type":"ISBN_13","identifier":"9780786417018"}],"readingModes":{"text":true,"image":true},"pageCount":288,"printType":"BOOK","categories":["History"],"maturityRating":"NOT_MATURE","allowAnonLogging":false,"contentVersion":"0.11.14.0.preview.3","panelizationSummary":{"containsEpubBubbles":false,"containsImageBubbles":false},"imageLinks":{"smallThumbnail":"http://books.google.com/books/content?id=CMPx-jksa6IC&printsec=frontcover&img=1&zoom=5&edge=curl&source=gbs_api","thumbnail":"http://books.google.com/books/content?id=CMPx-jksa6IC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api"},"language":"en","previewLink":"http://books.google.co.jp/books?id=CMPx-jksa6IC&pg=PP13&dq=h&hl=&cd=1&source=gbs_api","infoLink":"http://books.google.co.jp/books?id=CMPx-jksa6IC&dq=h&hl=&source=gbs_api","canonicalVolumeLink":"https://books.google.com/books/about/Watching_M_A_S_H_Watching_America.html?hl=&id=CMPx-jksa6IC"},"saleInfo":{"country":"JP","saleability":"NOT_FOR_SALE","isEbook":false},"accessInfo":{"country":"JP","viewability":"PARTIAL","embeddable":true,"publicDomain":false,"textToSpeechPermission":"ALLOWED","epub":{"isAvailable":true,"acsTokenLink":"http://books.google.co.jp/books/download/Watching_M_A_S_H_Watching_America-sample-epub.acsm?id=CMPx-jksa6IC&format=epub&output=acs4_fulfillment_token&dl_type=sample&source=gbs_api"},"pdf":{"isAvailable":true,"acsTokenLink":"http://books.google.co.jp/books/download/Watching_M_A_S_H_Watching_America-sample-pdf.acsm?id=CMPx-jksa6IC&format=pdf&output=acs4_fulfillment_token&dl_type=sample&source=gbs_api"},"webReaderLink":"http://play.google.com/books/reader?id=CMPx-jksa6IC&hl=&source=gbs_api","accessViewStatus":"SAMPLE","quoteSharingAllowed":false},"searchInfo":{"textSnippet":"A Social History of the 1972-1983 Television Series James <b>H</b>. Wittebols. social and cultural milieu in which the planning and development of M * A * S * <b>H</b> occurred . As the &quot; first draft of history , &quot; journalistic accounts allow us to&nbsp;..."}}');
INSERT INTO google_book values ("gX9oRcT9kSgC", "Peptide Solvation and H-bonds", '{"kind":"books#volume","id":"gX9oRcT9kSgC","etag":"GYOpSOBy7Pw","selfLink":"https://www.googleapis.com/books/v1/volumes/gX9oRcT9kSgC","volumeInfo":{"title":"Peptide Solvation and H-bonds","publisher":"Elsevier","publishedDate":"2006-03-02","description":"Volume 72, Peptide Solvation and H-bonds, addresses the role of peptide backbone solvation in the energetics of protein folding. Particular attention is focused on modeling and computation. This volume will be of particular interest to biophysicists and structural biologists. - Challenges the longstanding and basic assumptions of structural biology - Discusses how to solve the problem of protein structure prediction - Addresses the quantitation of the energetics of folding","industryIdentifiers":[{"type":"ISBN_13","identifier":"9780080463568"},{"type":"ISBN_10","identifier":"0080463568"}],"readingModes":{"text":true,"image":true},"pageCount":313,"printType":"BOOK","categories":["Science"],"maturityRating":"NOT_MATURE","allowAnonLogging":false,"contentVersion":"2.4.5.0.preview.3","panelizationSummary":{"containsEpubBubbles":false,"containsImageBubbles":false},"imageLinks":{"smallThumbnail":"http://books.google.com/books/content?id=gX9oRcT9kSgC&printsec=frontcover&img=1&zoom=5&edge=curl&source=gbs_api","thumbnail":"http://books.google.com/books/content?id=gX9oRcT9kSgC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api"},"language":"en","previewLink":"http://books.google.co.jp/books?id=gX9oRcT9kSgC&pg=PR9&dq=h&hl=&cd=2&source=gbs_api","infoLink":"https://play.google.com/store/books/details?id=gX9oRcT9kSgC&source=gbs_api","canonicalVolumeLink":"https://play.google.com/store/books/details?id=gX9oRcT9kSgC"},"saleInfo":{"country":"JP","saleability":"FOR_SALE","isEbook":true,"listPrice":{"amount":19250,"currencyCode":"JPY"},"retailPrice":{"amount":17325,"currencyCode":"JPY"},"buyLink":"https://play.google.com/store/books/details?id=gX9o