INSERT INTO google_book values ("TkGdEQAAQBAJ", "Philip K. Dick", '{"kind":"books#volume","id":"TkGdEQAAQBAJ","etag":"jOPwif49cwg","selfLink":"https://www.googleapis.com/books/v1/volumes/TkGdEQAAQBAJ","volumeInfo":{"title":"Philip K. Dick","authors":["Laurent Queyssi","Mauro Marchesi"],"publisher":"NBM Publishing","publishedDate":"2019-01-01","description":"Discover the improbable life of the author behind Blade Runner and Minority Report in this comics biography. Explore the fascinating and turbulent life of Philip K. Dick, the visionary science fiction author whose works have captivated readers and inspired iconic films. This graphic novel delves into Dick''s personal struggles, creative genius, and the alternate realities that shaped his unique perspective. Follow Dick''s journey from his early influences to his battles with mental health and drug use, and his eventual rise to literary fame. This biography offers a unique perspective on a brilliant mind that continues to influence our world. Perfect for fans of science fiction, comics, and anyone interested in the life of a literary icon.","industryIdentifiers":[{"type":"ISBN_13","identifier":"9781681121932"},{"type":"ISBN_10","identifier":"168112193X"}],"readingModes":{"text":true,"image":true},"pageCount":146,"printType":"BOOK","categories":["Comics & Graphic Novels"],"maturityRating":"NOT_MATURE","allowAnonLogging":false,"contentVersion":"0.1.1.0.preview.3","panelizationSummary":{"containsEpubBubbles":true,"containsImageBubbles":true,"epubBubbleVersion":"4e083f6dffa604ac_A","imageBubbleVersion":"4e083f6dffa604ac_A"},"imageLinks":{"smallThumbnail":"http://books.google.com/books/content?id=TkGdEQAAQBAJ&printsec=frontcover&img=1&zoom=5&edge=curl&source=gbs_api","thumbnail":"http://books.google.com/books/content?id=TkGdEQAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api"},"language":"en","previewLink":"http://books.google.co.jp/books?id=TkGdEQAAQBAJ&pg=PA9&dq=k&hl=&cd=2&source=gbs_api","infoLink":"h