INSERT INTO google_book values ("vg_rEAAAQBAJ", "M-1グランプリ2023完全ガイドブック", '{"kind":"books#volume","id":"vg_rEAAAQBAJ","etag":"8MlZhW/e8xM","selfLink":"https://www.googleapis.com/books/v1/volumes/vg_rEAAAQBAJ","volumeInfo":{"title":"M-1グランプリ2023完全ガイドブック","authors":["ヨシモトブックス/ABCアーク"],"publisher":"ABCアーク","publishedDate":"2023-12-13","description":"※この商品はタブレットなど大きいディスプレイを備えた端末で読むことに適しています。また、文字だけを拡大することや、文字列のハイライト、検索、辞書の参照、引用などの機能が使用できません。 ファイナリストや敗者復活戦に出場する漫才師たちのプロフィールに、8540組の頂点を目指す各組の意気込みなど、最新かつ熱い情報を網羅したガイドブックを発売します！今年の出場者だけでなく、昨年の王者ウエストランドによる巻頭インタビューをはじめ、千鳥やかまいたち、スピードワゴンといった「M-1」で実力を見せつけた人気お笑いコンビや、昨年が「M-1」ラストイヤーとなった金属バット、見取り図、ランジャタイ、ぺこぱら、錚々たるメンバーのインタビューなど盛りだくさんです。","industryIdentifiers":[{"type":"OTHER","identifier":"PKEY:BT000149721100100101900209"}],"readingModes":{"text":true,"image":true},"pageCount":98,"printType":"BOOK","categories":["Computers"],"maturityRating":"NOT_MATURE","allowAnonLogging":false,"contentVersion":"1.2.0.0.preview.3","panelizationSummary":{"containsEpubBubbles":false,"containsImageBubbles":false},"imageLinks":{"smallThumbnail":"http://books.google.com/books/content?id=vg_rEAAAQBAJ&printsec=frontcover&img=1&zoom=5&edge=curl&source=gbs_api","thumbnail":"http://books.google.com/books/content?id=vg_rEAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api"},"language":"ja","previewLink":"http://books.google.co.jp/books?id=vg_rEAAAQBAJ&pg=PA50&dq=m&hl=&cd=1&source=gbs_api","infoLink":"http://books.google.co.jp/books?id=vg_rEAAAQBAJ&dq=m&hl=&source=gbs_api","canonicalVolumeLink":"https://books.google.com/books/about/M_1%E3%82%B0%E3%83%A9%E3%83%B3%E3%83%97%E3%83%AA2023%E5%AE%8C%E5%85%A8%E3%82%AC%E3%82%A4%E3%83%89%E3%83%96.html?hl=&id=vg_rEAAAQBAJ"},"saleInfo":{"country":"JP","saleability":"NOT_FOR_SALE","isEbook":false},"accessInfo":{"country":"JP","viewability":"PARTIAL","embeddable":true,"publicDomain":false,"textToSpeechPermission":"ALLOWED","epub":{"isAvailable":true,"acsTokenLink":"http://books.google.co.jp/books/download/M_1%E3%82%B