INSERT INTO google_book values ("Ja3W4Zsv4ykC", "M Programming: A Comprehensive Guide", '{"kind":"books#volume","id":"Ja3W4Zsv4ykC","etag":"GQpaNeHxnEU","selfLink":"https://www.googleapis.com/books/v1/volumes/Ja3W4Zsv4ykC","volumeInfo":{"title":"M Programming: A Comprehensive Guide","authors":["Richard Walters"],"publisher":"Elsevier","publishedDate":"1997-06-06","description":"M Programming: A Comprehensive Guide is a complete update to ABCs of MUMPS. While ABCs of MUMPS was an introduction for novice and intermediate M programmers, M Programming: A Comprehensive Guide has a new section containing advanced material. This new section addresses features such as transaction processing, networking, structured system variables, and interfaces to other standards. Five new chapters have been added, covering an overview of M for readers familiar with other languages; M and the Windows environment; interaction between M and the underlying system; transaction processing; interfacing M with other standards; and error handling. Sections on interactive programming and futures have been extensively updated. M Programming: A Comprehensive Guide is an invaluable resource for everyone who is learning or using M.· Includes section on advanced programming· Completely updated for the 1995 standard","industryIdentifiers":[{"type":"ISBN_13","identifier":"9780080510514"},{"type":"ISBN_10","identifier":"0080510515"}],"readingModes":{"text":true,"image":true},"pageCount":428,"printType":"BOOK","categories":["Computers"],"averageRating":1,"ratingsCount":1,"maturityRating":"NOT_MATURE","allowAnonLogging":true,"contentVersion":"1.4.3.0.preview.3","panelizationSummary":{"containsEpubBubbles":false,"containsImageBubbles":false},"imageLinks":{"smallThumbnail":"http://books.google.com/books/content?id=Ja3W4Zsv4ykC&printsec=frontcover&img=1&zoom=5&edge=curl&source=gbs_api","thumbnail":"http://books.google.com/books/content?id=Ja3W4Zsv4ykC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api"}