INSERT INTO google_book values ("L3OrEQAAQBAJ", "AUTO STYLE Vol.41 HONDA N-ONE&Nシリーズ*02", '{"kind":"books#volume","id":"L3OrEQAAQBAJ","etag":"Ti4Evl8d4bA","selfLink":"https://www.googleapis.com/books/v1/volumes/L3OrEQAAQBAJ","volumeInfo":{"title":"AUTO STYLE Vol.41 HONDA N-ONE&Nシリーズ*02","authors":["交通タイムス社"],"publisher":"交通タイムス社","publishedDate":"2022-11-21","description":"※電子書籍版は紙版と一部内容が異なり、目次に掲載している記事、画像、広告、付録、読者プレゼント応募などが含まれない場合がございます。 希少なマニュアルモデルをラインナップするホンダ N-ONE。ドレスアップするにしてもチューニングするにしても、とてもカスタムしがいのある人気の軽モデルです。またオーナーの楽しみ方も多彩なのがN-ONEの特徴でもあります。そんな同車ゆえ、カスタムモデルやパーツ群はとても豊富。昨年のvol.1に続く本書では、N-ONEの様々な【最新の】楽しみ方を多数紹介します。ホンダ渾身のNシリーズ。そんないまどきのクルマたちの楽しみ方や最新情報を満載した１冊です。 ＜主な内容＞ ★ A LIFE with N オーナー編 ★ 原点から最新まで、Nを愛する4 人のオーナーたち ★ NEW CARS メーカー編 ★ 開発者が語る“N”のコダワリ、イイトコロ ★ STYLING カスタム＆チューニング編 ★ モデューロ/無限/レイズ/MID WHEELS/YFC/ブリッツ/HKS/ブリッド ★ カスタムのプロが提案するホイール選びの実例集 ★ ［SNS で見つけた］N ユーザーの足元メイクアップ集 ★ OUTDOORS アウトドア編 ★ ホンダアクセス/ダムド/フォレストオート ★ 魅力たっぷりのN-ONE オーナーズカップ ★ WHEEL CATALOG ★ パーツカタログ for N Series","industryIdentifiers":[{"type":"OTHER","identifier":"PKEY:CR000000000001282000"}],"readingModes":{"text":true,"image":true},"pageCount":132,"printType":"BOOK","categories":["Travel"],"maturityRating":"NOT_MATURE","allowAnonLogging":false,"contentVersion":"1.1.0.0.preview.3","panelizationSummary":{"containsEpubBubbles":false,"containsImageBubbles":false},"imageLinks":{"smallThumbnail":"http://books.google.com/books/content?id=L3OrEQAAQBAJ&printsec=frontcover&img=1&zoom=5&edge=curl&source=gbs_api","thumbnail":"http://books.google.com/books/content?id=L3OrEQAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api"},"language":"ja","previewLink":"http://books.google.co.jp/books?id=L3OrEQAAQBAJ&pg=PA116&dq=n&hl=&cd=2&source=gbs_api","infoLink":"https://play.google.com/store/books/details?id=L3OrEQAAQBAJ&source=gbs_api","canonicalVolumeLink":"https://play.google.com/store/books/details?id=L3OrEQAAQBAJ"},"saleInfo":{"country":"JP","saleability":"FOR_SALE","isEbook":true,"listPrice":{"amount":