INSERT INTO google_book values ("9vjfvsoBjXQC", "August Spies Et Al., Plaintiffs in Error", '{"kind":"books#volume","id":"9vjfvsoBjXQC","etag":"G6cWc1kJefg","selfLink":"https://www.googleapis.com/books/v1/volumes/9vjfvsoBjXQC","volumeInfo":{"title":"August Spies Et Al., Plaintiffs in Error","subtitle":"Vs. The People of the State of Illinois, Defendants in Error. Error to the Criminal Court of Cook County. Brief on the Facts for Defendants in Error. George Hunt, Attorney General. Julius S. Grinnell, States Attorney. George C. Ingham, of Counsel. Francis W. Walker, Edmund Furthman , Asst. States Attorneys","authors":["Illinois. Attorney General''s Office"],"publishedDate":"1887","industryIdentifiers":[{"type":"OTHER","identifier":"WISC:89073020331"}],"readingModes":{"text":false,"image":true},"pageCount":360,"printType":"BOOK","categories":["Anarchism"],"maturityRating":"NOT_MATURE","allowAnonLogging":false,"contentVersion":"0.5.6.0.full.1","panelizationSummary":{"containsEpubBubbles":false,"containsImageBubbles":false},"imageLinks":{"smallThumbnail":"http://books.google.com/books/content?id=9vjfvsoBjXQC&printsec=frontcover&img=1&zoom=5&edge=curl&source=gbs_api","thumbnail":"http://books.google.com/books/content?id=9vjfvsoBjXQC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api"},"language":"en","previewLink":"http://books.google.co.jp/books?id=9vjfvsoBjXQC&pg=PA178&dq=q&hl=&cd=9&source=gbs_api","infoLink":"https://play.google.com/store/books/details?id=9vjfvsoBjXQC&source=gbs_api","canonicalVolumeLink":"https://play.google.com/store/books/details?id=9vjfvsoBjXQC"},"saleInfo":{"country":"JP","saleability":"FREE","isEbook":true,"buyLink":"https://play.google.com/store/books/details?id=9vjfvsoBjXQC&rdid=book-9vjfvsoBjXQC&rdot=1&source=gbs_api"},"accessInfo":{"country":"JP","viewability":"ALL_PAGES","embeddable":true,"publicDomain":true,"textToSpeechPermission":"ALLOWED","epub":{"isAvailable":false,"downloadLink":"http://books.google.co.jp/books/download/August_S