INSERT INTO google_book values ("B2z7EQAAQBAJ", "GT-R Magazine(ジーティーアールマガジン) 2026年 9月号", '{"kind":"books#volume","id":"B2z7EQAAQBAJ","etag":"nhHcFxDYZBc","selfLink":"https://www.googleapis.com/books/v1/volumes/B2z7EQAAQBAJ","volumeInfo":{"title":"GT-R Magazine(ジーティーアールマガジン) 2026年 9月号","authors":["GT-RMagazine編集部"],"publisher":"交通タイムス社","publishedDate":"2026-07-31","description":"※電子書籍版は紙版と一部内容が異なり、目次に掲載している記事、画像、広告、付録、読者プレゼント応募などが含まれない場合がございます。 この先を見据えた最新メニューでGT-Rらしさを保つ！「GT-R」に特化した誌面構成でお届けしている本誌「GT-R Magazine」は、ハコスカ／ケンメリ、R32/R33/R34、そしてR35、全てのGT-Rオーナーならびにファンに向けて情報を発信し続けています。 今号のトピックスは、往年のマシン2台の特集。1台はNISMO 400R。NISMOが1996年に発売したコンプリートカーを30年目となる今、夜と早朝の街に連れ出してみました。もう1台はチューニングブームの1990年代後半に一斉を風靡したS ROCをトラスト自ら現代の技術を投入した復刻版を製作中。さらに本誌BNR34Nur号の足まわりリフレッシュ。4つのアイテムを刷新して、走り味をアップデートを敢行しました。そのほかにもGT-Rオーナー、そしてファンに役立つ情報を満載しています。 【コンテンツ紹介】 ●生誕30周年を迎えた伝説のデモカー「NISMO 400R 『再会』」 ●『TRUST』が手がける第2世代Rチューン新世界「The Blue Rockrts」 ●本誌ニュル号の4つのアイテムを刷新「R34の走りを変える新たなアプローチ」 ●「松田次生」険路平踏の軌跡「執念で取ったスーパーGT“25勝”」 ●製廃されてユニットの修理もできない「ABSトラブルは突然やってくる」 ●知っているようで知らない？「R35・GR6再診メンテナンス術」","industryIdentifiers":[{"type":"OTHER","identifier":"PKEY:CR000000000001322103"}],"readingModes":{"text":true,"image":true},"pageCount":140,"printType":"BOOK","categories":["Transportation"],"maturityRating":"NOT_MATURE","allowAnonLogging":false,"contentVersion":"preview-1.0.0","panelizationSummary":{"containsEpubBubbles":false,"containsImageBubbles":false},"imageLinks":{"smallThumbnail":"http://books.google.com/books/content?id=B2z7EQAAQBAJ&printsec=frontcover&img=1&zoom=5&edge=curl&source=gbs_api","thumbnail":"http://books.google.com/books/content?id=B2z7EQAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api"},"language":"ja","previewLink":"http://books.google.co.jp/books?id=B2z7EQAAQBAJ&pg=PA121&dq=r&hl=&cd=6&source=gbs_api","infoLink":"https://play.google.com/store/books/details?id=B2z7EQAAQBAJ&source=gbs_api","canonicalVolumeLink":"https://play.google.com/store/books/details?id=B2z7EQAAQBAJ"},"saleInfo":{"country