INSERT INTO google_book values ("DtNqJXQFphMC", "Artificial Market Experiments with the U-Mart System", '{"kind":"books#volume","id":"DtNqJXQFphMC","etag":"n0YdgfeLkkU","selfLink":"https://www.googleapis.com/books/v1/volumes/DtNqJXQFphMC","volumeInfo":{"title":"Artificial Market Experiments with the U-Mart System","authors":["Yoshinori Shiozawa","Yoshihiro Nakajima","Hiroyuki Matsui","Yuhsuke Koyama","Kazuhisa Taniguchi","Fumihiko Hashimoto"],"publisher":"Springer Science & Business Media","publishedDate":"2008-04-09","description":"Economics went through great development in the 20th century. This development, which was based mainly on mathematical methods, is not an appropriate method of analyzing markets that change every hour and every day. In a stock market, prices constantly change depending on speculation. U-Mart, a manmade market, has been proposed in order to study such instantly moving markets. Although the U-Mart system is internationally acclaimed for being at the forefront of market research, its use is by no means limited to a small number of researchers on the fringe. The whole system, including its source code, is open and is distributed without charge, testifying to a philosophy of creating and providing a common test bed for research into financial markets.","industryIdentifiers":[{"type":"ISBN_13","identifier":"9784431768234"},{"type":"ISBN_10","identifier":"4431768238"}],"readingModes":{"text":true,"image":true},"pageCount":173,"printType":"BOOK","categories":["Business & Economics"],"maturityRating":"NOT_MATURE","allowAnonLogging":false,"contentVersion":"3.7.9.0.preview.3","panelizationSummary":{"containsEpubBubbles":false,"containsImageBubbles":false},"imageLinks":{"smallThumbnail":"http://books.google.com/books/content?id=DtNqJXQFphMC&printsec=frontcover&img=1&zoom=5&edge=curl&source=gbs_api","thumbnail":"http://books.google.com/books/content?id=DtNqJXQFphMC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api"},"language":"en","previewLi