INSERT INTO google_book values ("gczsCgAAQBAJ", "W-symmetry", '{"kind":"books#volume","id":"gczsCgAAQBAJ","etag":"z13VR6nkz+8","selfLink":"https://www.googleapis.com/books/v1/volumes/gczsCgAAQBAJ","volumeInfo":{"title":"W-symmetry","authors":["Peter Bouwknegt","Kareljan Schoutens"],"publisher":"World Scientific","publishedDate":"1995-01-10","description":"W-symmetry is an extension of conformal symmetry in two dimensions. Since its introduction in 1985, W-symmetry has become one of the central notions in the study of two-dimensional conformal field theory. The mathematical structures that underlie W-symmetry are so-called W-algebras, which are higher-spin extensions of the Virasoro algebra. This book contains a collection of papers on W-symmetry, covering the period from 1985 through 1993. Its main focus is the construction of W-algebras and their representation theory. A recurrent theme is the intimate connection between W-algebras and affine Lie algebras. Some of the applications, in particular W-gravity, are also covered.The significance of this reprint volume is that there are no textbooks entirely devoted to the subject.","industryIdentifiers":[{"type":"ISBN_13","identifier":"9789814501996"},{"type":"ISBN_10","identifier":"9814501999"}],"readingModes":{"text":false,"image":true},"pageCount":903,"printType":"BOOK","categories":["Science"],"maturityRating":"NOT_MATURE","allowAnonLogging":false,"contentVersion":"1.2.1.0.preview.1","panelizationSummary":{"containsEpubBubbles":false,"containsImageBubbles":false},"imageLinks":{"smallThumbnail":"http://books.google.com/books/content?id=gczsCgAAQBAJ&printsec=frontcover&img=1&zoom=5&edge=curl&source=gbs_api","thumbnail":"http://books.google.com/books/content?id=gczsCgAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api"},"language":"en","previewLink":"http://books.google.co.jp/books?id=gczsCgAAQBAJ&pg=PA733&dq=w&hl=&cd=1&source=gbs_api","infoLink":"https://play.google.com/store/books/details?id=gczsCgAAQBAJ&