INSERT INTO google_book values ("yYQvAQAAQBAJ", "162-0: Imagine a Red Sox Perfect Season", '{"kind":"books#volume","id":"yYQvAQAAQBAJ","etag":"o0J8n48664w","selfLink":"https://www.googleapis.com/books/v1/volumes/yYQvAQAAQBAJ","volumeInfo":{"title":"162-0: Imagine a Red Sox Perfect Season","subtitle":"The Greatest Wins!","authors":["Mark Cofman"],"publisher":"Triumph Books","publishedDate":"2010-03-01","description":"In a series that imagines the impossible, each book plays out a flawless season for a particular team, identifying the most memorable real-life victory on every single day of the baseball calendar and including archival photos, original quotes and thorough research.","industryIdentifiers":[{"type":"ISBN_13","identifier":"9781600783456"},{"type":"ISBN_10","identifier":"1600783457"}],"readingModes":{"text":false,"image":true},"pageCount":305,"printType":"BOOK","categories":["Sports & Recreation"],"maturityRating":"NOT_MATURE","allowAnonLogging":false,"contentVersion":"0.2.2.0.preview.1","panelizationSummary":{"containsEpubBubbles":false,"containsImageBubbles":false},"imageLinks":{"smallThumbnail":"http://books.google.com/books/content?id=yYQvAQAAQBAJ&printsec=frontcover&img=1&zoom=5&edge=curl&source=gbs_api","thumbnail":"http://books.google.com/books/content?id=yYQvAQAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api"},"language":"en","previewLink":"http://books.google.co.jp/books?id=yYQvAQAAQBAJ&pg=PA42&dq=0&hl=&cd=1&source=gbs_api","infoLink":"http://books.google.co.jp/books?id=yYQvAQAAQBAJ&dq=0&hl=&source=gbs_api","canonicalVolumeLink":"https://books.google.com/books/about/162_0_Imagine_a_Red_Sox_Perfect_Season.html?hl=&id=yYQvAQAAQBAJ"},"saleInfo":{"country":"JP","saleability":"NOT_FOR_SALE","isEbook":false},"accessInfo":{"country":"JP","viewability":"PARTIAL","embeddable":true,"publicDomain":false,"textToSpeechPermission":"ALLOWED","epub":{"isAvailable":false},"pdf":{"isAvailable":true,"acsTokenLink":"http://books.google.co.jp/books/down