INSERT INTO google_book values ("PLLdBAAAQBAJ", "Scientia Magna, Vol. 3, No. 1, 2007.", '{"kind":"books#volume","id":"PLLdBAAAQBAJ","etag":"qgZdUo717R0","selfLink":"https://www.googleapis.com/books/v1/volumes/PLLdBAAAQBAJ","volumeInfo":{"title":"Scientia Magna, Vol. 3, No. 1, 2007.","subtitle":"international book series","authors":["Zhang Wenpeng","Hailong Li"],"publisher":"Infinite Study","description":"Third International Conference on Number Theory and Smarandache Problems, 23-25 March 2007, Weinan Teacher''s University, China. Papers on Smarandache multi-spaces and mathematical combinatorics, Smarandache stepped functions, cube-free integers as sums of two squares, recurrences for generalized Euler numbers, the generalization of the primitive number function, the Smarandache LCM function and its mean value, a conjecture involving the F. Smarandache LCM function, a new arithmetical function and its asymptotic formula, and other similar topics. Contributors: J. Wang, A. Muktibodh, M. Selariu, X. Zhang, Y. Zhang, M. Liu, R. Zhang, S. Ma, L. Mao, and many others.","industryIdentifiers":[{"type":"ISBN_13","identifier":"9781599730257"},{"type":"ISBN_10","identifier":"1599730251"}],"readingModes":{"text":false,"image":true},"pageCount":123,"printType":"BOOK","maturityRating":"NOT_MATURE","allowAnonLogging":false,"contentVersion":"1.1.0.0.preview.1","panelizationSummary":{"containsEpubBubbles":false,"containsImageBubbles":false},"imageLinks":{"smallThumbnail":"http://books.google.com/books/content?id=PLLdBAAAQBAJ&printsec=frontcover&img=1&zoom=5&edge=curl&source=gbs_api","thumbnail":"http://books.google.com/books/content?id=PLLdBAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api"},"language":"en","previewLink":"http://books.google.co.jp/books?id=PLLdBAAAQBAJ&pg=PA100&dq=1&hl=&cd=6&source=gbs_api","infoLink":"https://play.google.com/store/books/details?id=PLLdBAAAQBAJ&source=gbs_api","canonicalVolumeLink":"https://play.google.com/store/books/details?id=PLL