INSERT INTO google_book values ("eDsqDwAAQBAJ", "TIME FOR KIDS® Practicing for STAAR Success: Reading: Grade 3", '{"kind":"books#volume","id":"eDsqDwAAQBAJ","etag":"0PYwZu84sKY","selfLink":"https://www.googleapis.com/books/v1/volumes/eDsqDwAAQBAJ","volumeInfo":{"title":"TIME FOR KIDS® Practicing for STAAR Success: Reading: Grade 3","authors":["Jennifer Prior"],"publisher":"Teacher Created Materials","publishedDate":"2017-01-01","description":"Boost third graders'' knowledge base and prepare them for the STAAR Reading test while expanding their knowledge bases. By implementing this resource into instruction, students will sharpen their comprehension and critical-thinking skills to build the stamina necessary to succeed on the state test. Featuring TIME for Kids content, this resource offers high-interest informational texts, engaging literature passages, and poems. Questions are carefully crafted to guide students as they approach the texts and share their understanding. These practice exercises help students with skills such as the following: making inferences and drawing conclusions analyzing the development of ideas or characters, identifying author''s viewpoint, and identifying main idea, theme, and supporting details. This must-have resource is perfect to help promote the use of skills needed for success in the 21st century.","industryIdentifiers":[{"type":"ISBN_13","identifier":"9781425817053"},{"type":"ISBN_10","identifier":"142581705X"}],"readingModes":{"text":false,"image":true},"pageCount":114,"printType":"BOOK","categories":["Language Arts & Disciplines"],"maturityRating":"NOT_MATURE","allowAnonLogging":true,"contentVersion":"0.1.1.0.preview.1","panelizationSummary":{"containsEpubBubbles":false,"containsImageBubbles":false},"imageLinks":{"smallThumbnail":"http://books.google.com/books/content?id=eDsqDwAAQBAJ&printsec=frontcover&img=1&zoom=5&edge=curl&source=gbs_api","thumbnail":"http://books.google.com/books/content?id=eDsqDwAAQBAJ&printsec=frontcover&img=