INSERT INTO google_book values ("kPdpBgAAQBAJ", "Spectrum Grade 5", '{"kind":"books#volume","id":"kPdpBgAAQBAJ","etag":"dhv+JWScfw0","selfLink":"https://www.googleapis.com/books/v1/volumes/kPdpBgAAQBAJ","volumeInfo":{"title":"Spectrum Grade 5","authors":["Spectrum"],"publisher":"Carson-Dellosa Publishing","publishedDate":"2015-02-02","description":"Spectrum(R) Grade Specific for Grade 5 includes focused practice for reading, language arts , and math mastery. Skills include grammar and usage, parts of speech and sentence types, vocabulary acquisition and usage, fractions and decimals, perimeter, area and volume, classifying geometric figures, preparing for algebra, and graphing on the coordinate plane. Spectrum Grade Specific workbooks contain focused practice for language arts mastery. Each book also includes a writer''s guide. Step-by-step instructions help children with planning, drafting, revising, proofreading, and sharing writing. The math activities build the skills that children need for math achievement and success. Children in grades 1 to 6 will find lessons and exercises that help them progress through increasingly difficult subject matter. Aligned to current state standards, Spectrum is your child’s path to language arts and math mastery.","industryIdentifiers":[{"type":"ISBN_13","identifier":"9781483824314"},{"type":"ISBN_10","identifier":"1483824314"}],"readingModes":{"text":false,"image":true},"pageCount":324,"printType":"BOOK","categories":["Juvenile Nonfiction"],"maturityRating":"NOT_MATURE","allowAnonLogging":true,"contentVersion":"0.8.2.0.preview.1","panelizationSummary":{"containsEpubBubbles":false,"containsImageBubbles":false},"imageLinks":{"smallThumbnail":"http://books.google.com/books/content?id=kPdpBgAAQBAJ&printsec=frontcover&img=1&zoom=5&edge=curl&source=gbs_api","thumbnail":"http://books.google.com/books/content?id=kPdpBgAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api"},"language":"en","previewLink":"http://books.google.co.jp/books?id=kPdpBgAAQBAJ&pg=PA59&dq=5&hl=&cd=4&source=gbs_api","infoLink":"https://play.google.com/store/books/details?id=kPdpBgAAQBAJ&source=gbs_api","canonicalVolumeLink":"https://play.google.com/store/books/details?id=kPdpBgAAQBAJ"},"saleInfo":{"country":"JP","saleability":"FOR_SALE","isEbook":true,"listPrice":{"amount":2949,"currencyCode":"JPY"},"retailPrice":{"amount":2649,"currencyCode":"JPY"},"buyLink":"https://play.google.com/store/books/details?id=kPdpBgAAQBAJ&rdid=book-kPdpBgAAQBAJ&rdot=1&source=gbs_api","offers":[{"finskyOfferType":1,"listPrice":{"amountInMicros":2949000000,"currencyCode":"JPY"},"retailPrice":{"amountInMicros":2649000000,"currencyCode":"JPY"}}]},"accessInfo":{"country":"JP","viewability":"PARTIAL","embeddable":true,"publicDomain":false,"textToSpeechPermission":"ALLOWED","epub":{"isAvailable":false},"pdf":{"isAvailable":true},"webReaderLink":"http://play.google.com/books/reader?id=kPdpBgAAQBAJ&hl=&source=gbs_api","accessViewStatus":"SAMPLE","quoteSharingAllowed":false},"searchInfo":{"textSnippet":"... <b>5</b> 1,760 yards (yd .) 1 gallon (gal .) <b>5</b> 4 quarts (qt .) 1 mile (mi .) <b>5</b> 5,280 feet (ft .) 1 gallon (gal .) <b>5</b> 8 pints (pt .) 1 pound (lb .) <b>5</b> 16 ounces (oz .) 1 yard (yd .) <b>5</b> 36 inches (in .) 1 quart (qt .) <b>5</b> 2 pints (pt .) 1 yard (yd&nbsp;..."}}');
INSERT INTO google_book values ("N7ExEAAAQBAJ", "Seedfolks - Literature Kit Gr. 5-6", '{"kind":"books#volume","id":"N7ExEAAAQBAJ","etag":"jzoh+p9byyI","selfLink":"https://www.googleapis.com/books/v1/volumes/N7ExEAAAQBAJ","volumeInfo":{"title":"Seedfolks - Literature Kit Gr. 5-6","authors":["Chad Ibbotson"],"publisher":"Classroom Complete Press","publishedDate":"2020-06-16","description":"Strangers become a community in this heartwarming story about overcoming prejudices and finding a common ground. The vocabulary lists and quizzes create a complete resource that saves time while preparing these lessons. Students make predictions on how certain characters might be connected to each other. Analyze Leona''s comments about her experience dealing with officials to characterize her feelings towards them. Answer multiple choice questions about Virgil''s relationship with his father. Students explore Sae Young''s actions when the thunderstorm fills the rain collection barrels and relates this back to the themes of the book. Imagine being Virgil''s father and create a business plan for the baby lettuce idea. Detail how the setting of the book evolves with the characters in a transformation graphic organizer. Aligned to your State Standards and written to Bloom''s Taxonomy, additional crossword, word search, comprehension quiz and answer key are also included. About the Novel: Seedfolks follows the intertwining stories of several neighbors as they break down barriers and form a community. A vacant lot in Cleveland, Ohio is not the perfect spot for Kim to plant her lima beans. It''s too cold and there''s not very much sun. She does this anyways in honor of her father. Little does she know that this action will intrigue the neighbors she knows only as strangers, and cause a ripple effect throughout the neighborhood. Each chapter follows a different neighbor and their personal journey that brought them to this vacant lot. People of varying ages, genders, races and religions come together with a shared goal of growing their item of choice. Some want to start a business, while others want to win back a lost love. The garden blooms from a segregated group of individual plots into a real community as peoples'' guards are lowered and they begin to really know one another. When the season ends, only time will tell whether this new community will thrive.","industryIdentifiers":[{"type":"ISBN_13","identifier":"9780228305132"},{"type":"ISBN_10","identifier":"0228305136"}],"readingModes":{"text":false,"image":true},"pageCount":60,"printType":"BOOK","categories":["Education"],"maturityRating":"NOT_MATURE","allowAnonLogging":false,"contentVersion":"0.1.1.0.preview.1","panelizationSummary":{"containsEpubBubbles":false,"containsImageBubbles":false},"imageLinks":{"smallThumbnail":"http://books.google.com/books/content?id=N7ExEAAAQBAJ&printsec=frontcover&img=1&zoom=5&edge=curl&source=gbs_api","thumbnail":"http://books.google.com/books/content?id=N7ExEAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api"},"language":"en","previewLink":"http://books.google.co.jp/books?id=N7ExEAAAQBAJ&pg=PA51&dq=5&hl=&cd=5&source=gbs_api","infoLink":"https://play.google.com/store/books/details?id=N7ExEAAAQBAJ&source=gbs_api","canonicalVolumeLink":"https://play.google.com/store/books/details?id=N7ExEAAAQBAJ"},"saleInfo":{"country":"JP","saleability":"FOR_SALE","isEbook":true,"listPrice":{"amount":770,"currencyCode":"JPY"},"retailPrice":{"amount":693,"currencyCode":"JPY"},"buyLink":"https://play.google.com/store/books/details?id=N7ExEAAAQBAJ&rdid=book-N7ExEAAAQBAJ&rdot=1&source=gbs_api","offers":[{"finskyOfferType":1,"listPrice":{"amountInMicros":770000000,"currencyCode":"JPY"},"retailPrice":{"amountInMicros":693000000,"currencyCode":"JPY"}}]},"accessInfo":{"country":"JP","viewability":"PARTIAL","embeddable":true,"publicDomain":false,"textToSpeechPermission":"ALLOWED","epub":{"isAvailable":false},"pdf":{"isAvailable":true},"webReaderLink":"http://play.google.com/b