INSERT INTO google_book values ("7YGmCgAAQBAJ", "NIVAC Bundle 6: Gospels, Acts", '{"kind":"books#volume","id":"7YGmCgAAQBAJ","etag":"XhqGVgAlRUY","selfLink":"https://www.googleapis.com/books/v1/volumes/7YGmCgAAQBAJ","volumeInfo":{"title":"NIVAC Bundle 6: Gospels, Acts","authors":["Michael J. Wilkins","David E. Garland","Darrell L. Bock","Gary M. Burge","Ajith Fernando"],"publisher":"Zondervan Academic","publishedDate":"2015-11-03","description":"The NIV Application Commentary helps you communicate and apply biblical text effectively in today’'' context. To bring the ancient messages of the Bible into today''s world, each passage is treated in three sections: Original Meaning. Concise exegesis to help readers understand the original meaning of the biblical text in its historical, literary, and cultural context. Bridging Contexts. A bridge between the world of the Bible and the world of today, built by discerning what is timeless in the timely pages of the Bible. Contemporary Significance. This section identifies comparable situations to those faced in the Bible and explores relevant application of the biblical messages. The author alerts the readers of problems they may encounter when seeking to apply the passage and helps them think through the issues involved. This unique, award-winning commentary is the ideal resource for today''s preachers, teachers, and serious students of the Bible, giving them the tools, ideas, and insights they need to communicate God''s Word with the same powerful impact it had when it was first written.","industryIdentifiers":[{"type":"ISBN_13","identifier":"9780310530077"},{"type":"ISBN_10","identifier":"0310530075"}],"readingModes":{"text":true,"image":false},"pageCount":3580,"printType":"BOOK","categories":["Religion"],"maturityRating":"NOT_MATURE","allowAnonLogging":true,"contentVersion":"1.10.8.0.preview.2","panelizationSummary":{"containsEpubBubbles":false,"containsImageBubbles":false},"imageLinks":{"smallThumbnail":"http://books.goog