USE intern;

#------------------------------------------
# ユーザーTBL 作成
#------------------------------------------
DROP TABLE IF EXISTS user;
CREATE TABLE IF NOT EXISTS user
(
    user_id char(16) NOT NULL PRIMARY KEY,
    user_name varchar(100) NOT NULL,
    password char(16) NOT NULL,
    gender char(1) NOT NULL,
    auth char(1) NOT NULL,
    address varchar(150)
)
CHARACTER SET utf8mb4
COLLATE utf8mb4_0900_ai_ci;

#------------------------------------------
# 書籍TBL 作成
#------------------------------------------
DROP TABLE IF EXISTS book;
CREATE TABLE IF NOT EXISTS book
(
    isbn varchar(13) NOT NULL,
    book_id varchar(13) NOT NULL,
    title varchar(100) NOT NULL,
    description varchar(1024),
    img_url varchar(255),
    PRIMARY KEY(isbn,book_id)
)
CHARACTER SET utf8mb4
COLLATE utf8mb4_0900_ai_ci;

#------------------------------------------
# レンタルTBL 作成
#------------------------------------------
DROP TABLE IF EXISTS lending;
CREATE TABLE IF NOT EXISTS lending
(
    lending_user_id varchar(16) NOT NULL,
    isbn varchar(13) NOT NULL,
    book_id varchar(13) NOT NULL,
    rental_date Date NOT NULL,
    managed_user_id varchar(16) NOT NULL,
    return_plan_date Date NOT NULL,
    PRIMARY KEY(lending_user_id,isbn,rental_date)
)
CHARACTER SET utf8mb4
COLLATE utf8mb4_0900_ai_ci;

#------------------------------------------
# お知らせTBL 作成
#------------------------------------------
DROP TABLE IF EXISTS information;
CREATE TABLE IF NOT EXISTS information
(
    no SMALLINT NOT NULL,
    date DATE NOT NULL,
    title varchar(100) NOT NULL,
    content varchar(100) NOT NULL,
    PRIMARY KEY(no)
)
CHARACTER SET utf8mb4
COLLATE utf8mb4_0900_ai_ci;

#------------------------------------------
# 学生TBL 作成
#------------------------------------------
DROP TABLE IF EXISTS student;
CREATE TABLE IF NOT EXISTS student
(
    id varchar(8) NOT NULL,
    first_name varchar(20) NOT NULL,
    last_name varchar(20) NOT NULL,
    PRIMARY KEY(id)
)
CHARACTER SET utf8mb4
COLLATE utf8mb4_0900_ai_ci;

#------------------------------------------
# 書籍（Google books API）TBL 作成
#------------------------------------------
DROP TABLE IF EXISTS books;
DROP TABLE IF EXISTS google_book;
CREATE TABLE IF NOT EXISTS google_book
(
    book_id varchar(13) PRIMARY KEY,
    title varchar(100) NOT NULL,
    response_json json NOT NULL
)
CHARACTER SET utf8mb4
COLLATE utf8mb4_0900_ai_ci;

